import { useState } from "react";
import { useParams, Link } from "react-router-dom";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { api } from "../lib/api";
import {
  ArrowLeft,
  Calendar as CalendarIcon,
  Upload,
  Edit2,
  Lock,
  Save,
} from "lucide-react";

export const GameDetailPage = () => {
  const { id } = useParams();
  const queryClient = useQueryClient();
  const [isEditingFee, setIsEditingFee] = useState(false);
  const [feeInput, setFeeInput] = useState("");
  const [importText, setImportText] = useState("");

  const { data: game, isLoading } = useQuery({
    queryKey: ["games", id],
    queryFn: async () => {
      const { data } = await api.get<{ game: any }>(`/games/${id}`);
      return data.game;
    },
  });

  const updateGameMutation = useMutation({
    mutationFn: async (updates: { feeCents?: number; status?: string }) => {
      await api.patch(`/games/${id}`, updates);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["games", id] });
      setIsEditingFee(false);
    },
  });

  const importAttendanceMutation = useMutation({
    mutationFn: async (text: string) => {
      await api.post(`/games/${id}/attendance/import`, { text });
    },
    onSuccess: () => {
      setImportText("");
      queryClient.invalidateQueries({ queryKey: ["games", id] });
      queryClient.invalidateQueries({ queryKey: ["dashboard"] });
      queryClient.invalidateQueries({ queryKey: ["reconciliation"] });
      alert(
        "Import successful. Check Reconciliation Queue for mismatched names.",
      );
    },
  });

  const handleSaveFee = () => {
    const newFee = Number(feeInput);
    if (!isNaN(newFee)) {
      updateGameMutation.mutate({ feeCents: newFee });
    }
  };

  const handleImportSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (importText.trim()) {
      importAttendanceMutation.mutate(importText);
    }
  };

  const formatCurrency = (cents: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
    }).format(cents / 100);
  };

  if (isLoading)
    return (
      <div className="page-header">
        <h1 className="page-title">Loading...</h1>
      </div>
    );
  if (!game)
    return (
      <div className="page-header">
        <h1 className="page-title">Game Not Found</h1>
      </div>
    );

  return (
    <>
      <div style={{ marginBottom: "var(--spacing-md)" }}>
        <Link
          to="/games"
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: "4px",
            fontSize: "0.875rem",
            color: "var(--text-muted)",
          }}
        >
          <ArrowLeft size={16} /> Back to Games
        </Link>
      </div>

      <div className="page-header">
        <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
          <div
            style={{
              padding: "16px",
              borderRadius: "12px",
              backgroundColor: "rgba(59, 130, 246, 0.1)",
              color: "var(--primary)",
            }}
          >
            <CalendarIcon size={32} />
          </div>
          <div>
            <h1 className="page-title" style={{ marginBottom: "4px" }}>
              Game on {game.gameDate}
            </h1>
            <div style={{ display: "flex", gap: "8px", alignItems: "center" }}>
              <span
                style={{
                  padding: "2px 8px",
                  borderRadius: "99px",
                  fontSize: "0.75rem",
                  fontWeight: 600,
                  backgroundColor:
                    game.status === "completed"
                      ? "rgba(34, 197, 94, 0.1)"
                      : "rgba(59, 130, 246, 0.1)",
                  color:
                    game.status === "completed"
                      ? "var(--success)"
                      : "var(--primary)",
                  textTransform: "uppercase",
                }}
              >
                {game.status}
              </span>
              <span
                style={{
                  color: "var(--text-muted)",
                  fontSize: "0.875rem",
                  textTransform: "capitalize",
                }}
              >
                Source: {game.source}
              </span>
            </div>
          </div>
        </div>

        <div
          className="card"
          style={{
            padding: "16px",
            display: "flex",
            flexDirection: "column",
            gap: "8px",
            minWidth: "200px",
          }}
        >
          <span style={{ fontSize: "0.875rem", color: "var(--text-muted)" }}>
            Match Fee
          </span>

          {isEditingFee ? (
            <div style={{ display: "flex", gap: "8px", alignItems: "center" }}>
              <input
                type="number"
                className="input-field"
                style={{ width: "100px", padding: "4px 8px" }}
                value={feeInput}
                onChange={(e) => setFeeInput(e.target.value)}
              />
              <button
                className="btn btn-primary"
                style={{ padding: "6px" }}
                onClick={handleSaveFee}
              >
                <Save size={16} />
              </button>
              <button
                className="btn btn-outline"
                style={{ padding: "6px" }}
                onClick={() => setIsEditingFee(false)}
              >
                Cancel
              </button>
            </div>
          ) : (
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <span style={{ fontSize: "1.5rem", fontWeight: 700 }}>
                {formatCurrency(game.feeCents)}
              </span>
              {game.status === "completed" ? (
                <span title="Cannot edit completed game fee">
                  <Lock size={16} color="var(--text-muted)" />
                </span>
              ) : (
                <button
                  className="btn btn-outline"
                  style={{ padding: "4px" }}
                  onClick={() => {
                    setFeeInput(game.feeCents.toString());
                    setIsEditingFee(true);
                  }}
                >
                  <Edit2 size={14} />
                </button>
              )}
            </div>
          )}

          {game.status !== "completed" && (
            <button
              className="btn btn-outline"
              style={{
                width: "100%",
                marginTop: "8px",
                color: "var(--success)",
                borderColor: "var(--success)",
              }}
              onClick={() => updateGameMutation.mutate({ status: "completed" })}
              disabled={updateGameMutation.isPending}
            >
              Finalize Game
            </button>
          )}
        </div>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(400px, 1fr))",
          gap: "var(--spacing-lg)",
        }}
      >
        <div className="card" style={{ alignSelf: "start" }}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "var(--spacing-md)",
            }}
          >
            <h3 style={{ fontSize: "1.125rem", fontWeight: 600 }}>
              Attendance List ({game.attendance?.length || 0})
            </h3>
          </div>

          <div style={{ overflowX: "auto" }}>
            <table
              style={{
                width: "100%",
                borderCollapse: "collapse",
                textAlign: "left",
              }}
            >
              <thead>
                <tr style={{ borderBottom: "1px solid var(--border-color)" }}>
                  <th
                    style={{
                      padding: "8px",
                      color: "var(--text-secondary)",
                      fontWeight: 500,
                      fontSize: "0.875rem",
                    }}
                  >
                    Player
                  </th>
                  <th
                    style={{
                      padding: "8px",
                      color: "var(--text-secondary)",
                      fontWeight: 500,
                      fontSize: "0.875rem",
                    }}
                  >
                    Response
                  </th>
                  <th
                    style={{
                      padding: "8px",
                      color: "var(--text-secondary)",
                      fontWeight: 500,
                      fontSize: "0.875rem",
                    }}
                  >
                    Chargeable
                  </th>
                </tr>
              </thead>
              <tbody>
                {game.attendance?.length === 0 ? (
                  <tr>
                    <td
                      colSpan={3}
                      style={{
                        padding: "16px",
                        textAlign: "center",
                        color: "var(--text-muted)",
                      }}
                    >
                      No attendance records.
                    </td>
                  </tr>
                ) : (
                  game.attendance?.map(
                    (att: {
                      id: string;
                      playerId: string;
                      displayName: string;
                      sourceStatus: string;
                      chargeable: boolean;
                    }) => (
                      <tr
                        key={att.id}
                        style={{
                          borderBottom: "1px solid var(--border-color)",
                        }}
                      >
                        <td style={{ padding: "12px 8px", fontWeight: 500 }}>
                          <Link
                            to={`/players/${att.playerId}`}
                            style={{ color: "var(--text-primary)" }}
                          >
                            {att.displayName}
                          </Link>
                        </td>
                        <td
                          style={{
                            padding: "12px 8px",
                            textTransform: "capitalize",
                          }}
                        >
                          {att.sourceStatus}
                        </td>
                        <td style={{ padding: "12px 8px" }}>
                          <span
                            style={{
                              color: att.chargeable
                                ? "var(--warning)"
                                : "var(--text-muted)",
                            }}
                          >
                            {att.chargeable ? "Yes" : "No"}
                          </span>
                        </td>
                      </tr>
                    ),
                  )
                )}
              </tbody>
            </table>
          </div>
        </div>

        <div className="card" style={{ alignSelf: "start" }}>
          <h3
            style={{
              fontSize: "1.125rem",
              fontWeight: 600,
              marginBottom: "var(--spacing-md)",
              display: "flex",
              alignItems: "center",
              gap: "8px",
            }}
          >
            <Upload size={20} color="var(--primary)" />
            Import Facebook Poll
          </h3>
          <p
            style={{
              fontSize: "0.875rem",
              color: "var(--text-muted)",
              marginBottom: "var(--spacing-md)",
            }}
          >
            Copy and paste the attendee list from the Facebook event poll. Our
            engine will map names automatically.
          </p>
          <form onSubmit={handleImportSubmit}>
            <textarea
              className="input-field"
              rows={8}
              value={importText}
              onChange={(e) => setImportText(e.target.value)}
              placeholder="e.g. 5 Going: John Doe, Jane Smith
3 Defaulted: Bobby Tables
2 Can't go: Foo Bar"
              style={{
                resize: "vertical",
                marginBottom: "var(--spacing-md)",
                fontFamily: "monospace",
              }}
              required
            />
            <button
              type="submit"
              className="btn btn-primary"
              style={{ width: "100%" }}
              disabled={importAttendanceMutation.isPending}
            >
              {importAttendanceMutation.isPending
                ? "Importing..."
                : "Process Import"}
            </button>
          </form>
        </div>
      </div>
    </>
  );
};

import { useParams, Link } from "react-router-dom";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { api } from "../lib/api";
import { ArrowLeft, UserCircle, Plus } from "lucide-react";

export const PlayerDetailPage = () => {
  const { id } = useParams();
  const queryClient = useQueryClient();

  const { data: player, isLoading } = useQuery({
    queryKey: ["players", id],
    queryFn: async () => {
      const { data } = await api.get<{ player: any }>(`/players/${id}`);
      return data.player;
    },
  });

  const { data: aliases, isLoading: loadingAliases } = useQuery({
    queryKey: ["players", id, "aliases"],
    queryFn: async () => {
      const { data } = await api.get<{ aliases: any[] }>(
        `/players/${id}/aliases`,
      );
      return data.aliases;
    },
  });

  const { data: ledger, isLoading: loadingLedger } = useQuery({
    queryKey: ["players", id, "ledger"],
    queryFn: async () => {
      const { data } = await api.get(`/players/${id}/ledger?limit=50`);
      return data;
    },
  });

  const addAliasMutation = useMutation({
    mutationFn: async ({
      source,
      aliasRaw,
    }: {
      source: string;
      aliasRaw: string;
    }) => {
      await api.post(`/players/${id}/aliases`, { source, aliasRaw });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["players", id, "aliases"] });
    },
  });

  const handleAddAlias = () => {
    const raw = window.prompt("Enter new alias (e.g. facebook name):");
    if (raw?.trim()) {
      addAliasMutation.mutate({ source: "facebook", aliasRaw: raw.trim() });
    }
  };

  const formatCurrency = (cents: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
    }).format(cents / 100);
  };

  if (isLoading)
    return (
      <div className="page-header">
        <h1 className="page-title">Loading...</h1>
      </div>
    );
  if (!player)
    return (
      <div className="page-header">
        <h1 className="page-title">Player Not Found</h1>
      </div>
    );

  return (
    <>
      <div style={{ marginBottom: "var(--spacing-md)" }}>
        <Link
          to="/players"
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: "4px",
            fontSize: "0.875rem",
            color: "var(--text-muted)",
          }}
        >
          <ArrowLeft size={16} /> Back to Players
        </Link>
      </div>

      <div className="page-header">
        <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
          <UserCircle size={48} color="var(--primary)" />
          <div>
            <h1 className="page-title" style={{ marginBottom: 0 }}>
              {player.displayName}
            </h1>
            <p style={{ color: "var(--text-secondary)" }}>
              Added {new Date(player.createdAt).toLocaleDateString()}
            </p>
          </div>
        </div>
        <div>
          <span style={{ fontSize: "0.875rem", color: "var(--text-muted)" }}>
            Current Balance
          </span>
          <p
            style={{
              fontSize: "2rem",
              fontWeight: 700,
              textAlign: "right",
              color:
                player.currentBalanceCents > 0
                  ? "var(--warning)"
                  : "var(--text-primary)",
            }}
          >
            {formatCurrency(player.currentBalanceCents)}
          </p>
        </div>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 2fr",
          gap: "var(--spacing-lg)",
        }}
      >
        {/* Aliases Column */}
        <div className="card" style={{ alignSelf: "start" }}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "var(--spacing-md)",
            }}
          >
            <h3 style={{ fontSize: "1.125rem", fontWeight: 600 }}>
              Connected Aliases
            </h3>
            <button
              className="btn btn-outline"
              style={{ padding: "4px 8px" }}
              onClick={handleAddAlias}
            >
              <Plus size={16} />
            </button>
          </div>

          {loadingAliases ? (
            <p>Loading...</p>
          ) : aliases?.length === 0 ? (
            <p style={{ color: "var(--text-muted)", fontSize: "0.875rem" }}>
              No aliases configured.
            </p>
          ) : (
            <div
              style={{ display: "flex", flexDirection: "column", gap: "8px" }}
            >
              {aliases?.map(
                (alias: { id: string; alias_raw: string; source: string }) => (
                  <div
                    key={alias.id}
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      padding: "8px 12px",
                      backgroundColor: "var(--bg-base)",
                      borderRadius: "8px",
                      border: "1px solid var(--border-color)",
                    }}
                  >
                    <span style={{ fontWeight: 500 }}>{alias.alias_raw}</span>
                    <span
                      style={{
                        fontSize: "0.75rem",
                        color: "var(--text-muted)",
                        textTransform: "uppercase",
                      }}
                    >
                      {alias.source}
                    </span>
                  </div>
                ),
              )}
            </div>
          )}
        </div>

        {/* Ledger Column */}
        <div className="card">
          <h3
            style={{
              fontSize: "1.125rem",
              fontWeight: 600,
              marginBottom: "var(--spacing-md)",
            }}
          >
            Recent Transactions
          </h3>

          <div style={{ overflowX: "auto" }}>
            <table
              style={{
                width: "100%",
                borderCollapse: "collapse",
                textAlign: "left",
              }}
            >
              <thead>
                <tr style={{ borderBottom: "1px solid var(--border-color)" }}>
                  <th
                    style={{
                      padding: "8px",
                      color: "var(--text-secondary)",
                      fontWeight: 500,
                      fontSize: "0.875rem",
                    }}
                  >
                    Date
                  </th>
                  <th
                    style={{
                      padding: "8px",
                      color: "var(--text-secondary)",
                      fontWeight: 500,
                      fontSize: "0.875rem",
                    }}
                  >
                    Type
                  </th>
                  <th
                    style={{
                      padding: "8px",
                      color: "var(--text-secondary)",
                      fontWeight: 500,
                      fontSize: "0.875rem",
                    }}
                  >
                    Amount
                  </th>
                  <th
                    style={{
                      padding: "8px",
                      color: "var(--text-secondary)",
                      fontWeight: 500,
                      fontSize: "0.875rem",
                    }}
                  >
                    Details
                  </th>
                </tr>
              </thead>
              <tbody>
                {loadingLedger ? (
                  <tr>
                    <td colSpan={4}>Loading...</td>
                  </tr>
                ) : ledger?.data?.length === 0 ? (
                  <tr>
                    <td
                      colSpan={4}
                      style={{
                        padding: "16px",
                        textAlign: "center",
                        color: "var(--text-muted)",
                      }}
                    >
                      No transactions yet.
                    </td>
                  </tr>
                ) : (
                  ledger?.data?.map(
                    (entry: {
                      id: string;
                      created_at: string;
                      type: string;
                      amount_cents: number;
                      adjustment_reason?: string;
                    }) => (
                      <tr
                        key={entry.id}
                        style={{
                          borderBottom: "1px solid var(--border-color)",
                        }}
                      >
                        <td
                          style={{ padding: "12px 8px", fontSize: "0.875rem" }}
                        >
                          {new Date(entry.created_at).toLocaleDateString()}
                        </td>
                        <td style={{ padding: "12px 8px" }}>
                          <span
                            style={{
                              padding: "2px 6px",
                              borderRadius: "4px",
                              fontSize: "0.75rem",
                              textTransform: "uppercase",
                              fontWeight: 600,
                              backgroundColor:
                                entry.type === "charge"
                                  ? "rgba(239, 68, 68, 0.1)"
                                  : entry.type === "payment"
                                    ? "rgba(34, 197, 94, 0.1)"
                                    : "rgba(148, 163, 184, 0.1)",
                              color:
                                entry.type === "charge"
                                  ? "var(--danger)"
                                  : entry.type === "payment"
                                    ? "var(--success)"
                                    : "var(--text-secondary)",
                            }}
                          >
                            {entry.type}
                          </span>
                        </td>
                        <td style={{ padding: "12px 8px", fontWeight: 500 }}>
                          {entry.type === "charge"
                            ? "+"
                            : entry.type === "payment"
                              ? "-"
                              : ""}
                          {formatCurrency(entry.amount_cents)}
                        </td>
                        <td
                          style={{
                            padding: "12px 8px",
                            fontSize: "0.875rem",
                            color: "var(--text-muted)",
                          }}
                        >
                          {entry.type === "charge"
                            ? "Game fee"
                            : entry.type === "adjustment"
                              ? entry.adjustment_reason
                              : "Bank deposit"}
                        </td>
                      </tr>
                    ),
                  )
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </>
  );
};

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Link } from "react-router-dom";
import { api } from "../lib/api";
import {
  AlertCircle,
  Check,
  X,
  Search,
  ChevronLeft,
  ChevronRight,
} from "lucide-react";

export const ReconciliationPage = () => {
  const [page, setPage] = useState(0);
  const limit = 20;

  const queryClient = useQueryClient();

  const { data: queue, isLoading: loadingQueue } = useQuery({
    queryKey: ["reconciliation", page],
    queryFn: async () => {
      const { data } = await api.get(
        `/reconciliation-queue?limit=${limit}&offset=${page * limit}`,
      );
      return data;
    },
  });

  const { data: players } = useQuery({
    queryKey: ["players", "all-for-recon"],
    queryFn: async () => {
      const { data } = await api.get(`/players?limit=1000`);
      return data.data;
    },
  });

  const resolveMutation = useMutation({
    mutationFn: async ({ id, playerId }: { id: string; playerId: string }) => {
      await api.post(`/reconciliation-queue/${id}/resolve`, { playerId });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["reconciliation"] });
      queryClient.invalidateQueries({ queryKey: ["dashboard"] });
      queryClient.invalidateQueries({ queryKey: ["players"] });
      queryClient.invalidateQueries({ queryKey: ["games"] });
    },
  });

  const dismissMutation = useMutation({
    mutationFn: async (id: string) => {
      await api.post(`/reconciliation-queue/${id}/dismiss`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["reconciliation"] });
    },
  });

  const [resolvingId, setResolvingId] = useState<string | null>(null);

  const formatCurrency = (cents: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
    }).format(cents / 100);
  };

  return (
    <>
      <div className="page-header">
        <div>
          <h1 className="page-title" style={{ marginBottom: "4px" }}>
            Reconciliation Queue
          </h1>
          <p style={{ color: "var(--text-secondary)", fontSize: "0.875rem" }}>
            Items here require manual matching because the system couldn't
            confidently link them to a player.
          </p>
        </div>
      </div>

      <div className="card" style={{ padding: 0, overflow: "hidden" }}>
        <div style={{ overflowX: "auto" }}>
          <table
            style={{
              width: "100%",
              borderCollapse: "collapse",
              textAlign: "left",
            }}
          >
            <thead>
              <tr
                style={{
                  backgroundColor: "var(--bg-elevated)",
                  borderBottom: "1px solid var(--border-color)",
                }}
              >
                <th
                  style={{
                    padding: "12px 16px",
                    color: "var(--text-secondary)",
                    fontWeight: 500,
                    fontSize: "0.875rem",
                  }}
                >
                  Date
                </th>
                <th
                  style={{
                    padding: "12px 16px",
                    color: "var(--text-secondary)",
                    fontWeight: 500,
                    fontSize: "0.875rem",
                  }}
                >
                  Type
                </th>
                <th
                  style={{
                    padding: "12px 16px",
                    color: "var(--text-secondary)",
                    fontWeight: 500,
                    fontSize: "0.875rem",
                  }}
                >
                  Details
                </th>
                <th
                  style={{
                    padding: "12px 16px",
                    color: "var(--text-secondary)",
                    fontWeight: 500,
                    fontSize: "0.875rem",
                  }}
                >
                  Suggestion
                </th>
                <th
                  style={{
                    padding: "12px 16px",
                    color: "var(--text-secondary)",
                    fontWeight: 500,
                    fontSize: "0.875rem",
                    textAlign: "right",
                  }}
                >
                  Actions
                </th>
              </tr>
            </thead>
            <tbody>
              {loadingQueue ? (
                <tr>
                  <td
                    colSpan={5}
                    style={{ padding: "16px", textAlign: "center" }}
                  >
                    Loading...
                  </td>
                </tr>
              ) : queue?.data?.length === 0 ? (
                <tr>
                  <td
                    colSpan={5}
                    style={{ padding: "48px 16px", textAlign: "center" }}
                  >
                    <div
                      style={{
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                        gap: "12px",
                        color: "var(--text-muted)",
                      }}
                    >
                      <Check size={48} color="var(--success)" opacity={0.5} />
                      <p>You're all caught up! No items to reconcile.</p>
                    </div>
                  </td>
                </tr>
              ) : (
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                queue?.data?.map((item: any) => {
                  const payload = item.payload;
                  const isResolving = resolvingId === item.id;

                  return (
                    <tr
                      key={item.id}
                      style={{
                        borderBottom: "1px solid var(--border-color)",
                        transition: "background 0.2s",
                        backgroundColor: isResolving
                          ? "var(--bg-elevated)"
                          : "transparent",
                      }}
                    >
                      <td
                        style={{
                          padding: "16px",
                          fontSize: "0.875rem",
                          verticalAlign: "top",
                        }}
                      >
                        {new Date(item.createdAt).toLocaleDateString()}
                      </td>
                      <td style={{ padding: "16px", verticalAlign: "top" }}>
                        <span
                          style={{
                            padding: "4px 8px",
                            borderRadius: "4px",
                            fontSize: "0.75rem",
                            fontWeight: 600,
                            backgroundColor:
                              item.itemType === "attendance"
                                ? "rgba(59, 130, 246, 0.1)"
                                : "rgba(34, 197, 94, 0.1)",
                            color:
                              item.itemType === "attendance"
                                ? "var(--primary)"
                                : "var(--success)",
                            textTransform: "uppercase",
                          }}
                        >
                          {item.itemType}
                        </span>
                      </td>
                      <td style={{ padding: "16px", verticalAlign: "top" }}>
                        {item.itemType === "bank_transaction" ? (
                          <div>
                            <p style={{ fontWeight: 500, marginBottom: "4px" }}>
                              {payload.descriptionRaw} (
                              {payload.externalTxnId ||
                                payload.sourceRef ||
                                "Manual"}
                              )
                            </p>
                            <p
                              style={{
                                color: "var(--success)",
                                fontWeight: 600,
                              }}
                            >
                              {formatCurrency(payload.amountCents)}
                            </p>
                          </div>
                        ) : (
                          <div>
                            <p style={{ fontWeight: 500, marginBottom: "4px" }}>
                              "{payload.playerName}"
                            </p>
                            <p
                              style={{
                                color: "var(--text-muted)",
                                fontSize: "0.75rem",
                              }}
                            >
                              from Facebook import
                            </p>
                          </div>
                        )}
                      </td>
                      <td style={{ padding: "16px", verticalAlign: "top" }}>
                        {item.suggestedPlayerId ? (
                          <div>
                            <Link
                              to={`/players/${item.suggestedPlayerId}`}
                              style={{
                                fontWeight: 500,
                                color: "var(--primary)",
                              }}
                            >
                              {players?.find(
                                (p: any) => p.id === item.suggestedPlayerId,
                              )?.displayName || "Unknown Player"}
                            </Link>
                            <div
                              style={{
                                display: "flex",
                                alignItems: "center",
                                gap: "4px",
                                marginTop: "4px",
                                fontSize: "0.75rem",
                                color:
                                  item.confidence > 0.8
                                    ? "var(--success)"
                                    : "var(--warning)",
                              }}
                            >
                              <AlertCircle size={12} />
                              {(item.confidence * 100).toFixed(0)}% Match
                            </div>
                          </div>
                        ) : (
                          <span
                            style={{
                              color: "var(--text-muted)",
                              fontSize: "0.875rem",
                            }}
                          >
                            None
                          </span>
                        )}
                      </td>
                      <td
                        style={{
                          padding: "16px",
                          verticalAlign: "top",
                          textAlign: "right",
                        }}
                      >
                        {isResolving ? (
                          <div
                            style={{
                              display: "flex",
                              flexDirection: "column",
                              gap: "8px",
                              alignItems: "flex-end",
                              minWidth: "200px",
                            }}
                          >
                            <select
                              className="input-field"
                              style={{ width: "100%", padding: "6px" }}
                              onChange={(e) => {
                                if (e.target.value) {
                                  resolveMutation.mutate({
                                    id: item.id,
                                    playerId: e.target.value,
                                  });
                                  setResolvingId(null);
                                }
                              }}
                              defaultValue=""
                            >
                              <option value="" disabled>
                                Select Player...
                              </option>
                              {players?.map(
                                (p: { id: string; display_name: string }) => (
                                  <option key={p.id} value={p.id}>
                                    {p.display_name}
                                  </option>
                                ),
                              )}
                            </select>
                            <button
                              className="btn btn-outline"
                              style={{
                                fontSize: "0.75rem",
                                padding: "4px 8px",
                              }}
                              onClick={() => setResolvingId(null)}
                            >
                              Cancel
                            </button>
                          </div>
                        ) : (
                          <div
                            style={{
                              display: "flex",
                              gap: "8px",
                              justifyContent: "flex-end",
                            }}
                          >
                            {item.suggested_player_id && (
                              <button
                                className="btn btn-primary"
                                style={{
                                  padding: "6px 12px",
                                  display: "flex",
                                  alignItems: "center",
                                  gap: "4px",
                                }}
                                onClick={() =>
                                  resolveMutation.mutate({
                                    id: item.id,
                                    playerId: item.suggested_player_id,
                                  })
                                }
                                title="Accept Suggestion"
                              >
                                <Check size={16} /> Accept
                              </button>
                            )}
                            <button
                              className="btn btn-outline"
                              style={{
                                padding: "6px 12px",
                                display: "flex",
                                alignItems: "center",
                                gap: "4px",
                              }}
                              onClick={() => setResolvingId(item.id)}
                            >
                              <Search size={16} /> Find
                            </button>
                            <button
                              className="btn btn-outline"
                              style={{
                                padding: "6px",
                                color: "var(--danger)",
                                borderColor: "transparent",
                                backgroundColor: "rgba(239, 68, 68, 0.1)",
                              }}
                              onClick={() => dismissMutation.mutate(item.id)}
                              title="Dismiss / Ignore"
                            >
                              <X size={16} />
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {queue && queue.total > limit && (
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              padding: "16px",
              borderTop: "1px solid var(--border-color)",
            }}
          >
            <span
              style={{ fontSize: "0.875rem", color: "var(--text-secondary)" }}
            >
              Showing {queue.offset + 1} to{" "}
              {Math.min(queue.offset + limit, queue.total)} of {queue.total}
            </span>
            <div style={{ display: "flex", gap: "8px" }}>
              <button
                className="btn btn-outline"
                style={{ padding: "4px 8px" }}
                disabled={page === 0}
                onClick={() => setPage((p: number) => p - 1)}
              >
                <ChevronLeft size={16} />
              </button>
              <button
                className="btn btn-outline"
                style={{ padding: "4px 8px" }}
                disabled={(page + 1) * limit >= queue.total}
                onClick={() => setPage((p: number) => p + 1)}
              >
                <ChevronRight size={16} />
              </button>
            </div>
          </div>
        )}
      </div>
    </>
  );
};

